(95, 18, 72, '', 0.00, NULL, NULL, '2026-10-05 12:02:00', NULL, '{\"version\":1,\"context\":{\"question\":\"3e.2 Identifier les règles régissant les usages (droit à l’oubli, droit à l’image, droit d’auteur…)\",\"paragraph\":\"<p>Qu’est-ce que le droit à l’image ?  Cochez la ou les bonnes réponses.<\\/p><p>☐  C’est le fait d’autoriser ou de refuser la reproduction de votre image<\\/p><p>☐  C’est le droit d’utiliser votre image à partir du moment où vous la diffusez par vous-même<\\/p><p>☐  C’est le droit d’autoriser la diffusion publique de votre image<\\/p><p>☐  C’est le droit au respect de votre vie privée<\\/p><p>☐  C’est le droit de protection de votre image en tant que donnée personnelle<\\/p><p>Vrai ou faux :<\\/p><p>Publier la photo ou la vidéo sans l&#039;accord de la personne est sanctionné d&#039;un an d&#039;emprisonnement et de 15 000 € d&#039;amende.         ☐Vrai       ☐ Faux<\\/p><p>Photographier ou filmer une personne dans un lieu privé ou transmettre son image, sans son accord, est sanctionné d&#039;un an d&#039;emprisonnement seulement.<\\/p><p>☐Vrai       ☐ Faux<\\/p>\",\"context\":\"\",\"model_answer\":\"3e.2 Identifier les règles régissant les usages (droit à l’oubli, droit à l’image, droit d’auteur…)\\nQu’est-ce que le droit à l’image ?  Cochez la ou les bonnes réponses.\\n☒  C’est le fait d’autoriser ou de refuser la reproduction de votre image\\n☐  C’est le droit d’utiliser votre image à partir du moment où vous la diffusez par vous-même\\n☒  C’est le droit d’autoriser la diffusion publique de votre image\\n☒  C’est le droit au respect de votre vie privée\\n☒  C’est le droit de protection de votre image en tant que donnée personnelle\\nVrai ou faux :\\nPublier la photo ou la vidéo sans l\'accord de la personne est sanctionné d\'un an d\'emprisonnement et de 15 000 € d\'amende.         ☒Vrai       ☐ Faux\\nPhotographier ou filmer une personne dans un lieu privé ou transmettre son image, sans son accord, est sanctionné d\'un an d\'emprisonnement seulement.   ☐Vrai       ☒ Faux\",\"rubric\":\"A optimiser : 0-5\\/6 ☐\\nMaitrisé 6\\/6 ☐\\n\\nSOURCE MARKED ANSWERS (not configured automatic criteria):\\nC’est le fait d’autoriser ou de refuser la reproduction de votre image\\nC’est le droit d’autoriser la diffusion publique de votre image\\nC’est le droit au respect de votre vie privée\\nC’est le droit de protection de votre image en tant que donnée personnelle\\nVrai\\nFaux\\n\\nREVIEW:\\nSource transcription requires author review before publication\",\"keywords\":\"\",\"answer\":\"\",\"max_points\":6},\"suggestion\":{\"points\":null,\"method\":\"unconfigured\",\"matched\":[],\"total\":0}}', '2026-10-05 14:02:00'),
(96, 18, 73, '', 0.00, NULL, NULL, '2026-10-05 12:02:00', 0.00, '{\"version\":1,\"context\":{\"question\":\"3e.3 Gérer les différents paramètres (notamment ceux de confidentialité, sécurité…)\",\"paragraph\":\"<p>Vous souhaitez changer votre mot de passe, où allez-vous cliquer pour effectuer ce changement ?<\\/p><p>Indiquez dans quelle zone cliquer : Cliquez ou appuyez ici pour entrer du texte.<\\/p><p>………………………………………………………………………………………………………………………..<\\/p><img src=\\\"uploads\\/word_positionnement\\/27e0ad3596922c01.png\\\" alt=\\\"Illustration de l’exercice\\\" loading=\\\"lazy\\\">\",\"context\":\"\",\"model_answer\":\"3e.3 Gérer les différents paramètres (notamment ceux de confidentialité, sécurité…)\\nVous souhaitez changer votre mot de passe, où allez-vous cliquer pour effectuer ce changement ?\\nIndiquez dans quelle zone cliquer : MOT DE PASSE\",\"rubric\":\"A optimiser : 0\\/1 ☐\\nMaitrisé 1\\/1 ☐\\n\\nSOURCE MARKED ANSWERS (not configured automatic criteria):\\nMOT DE PASSE\\n\\nREVIEW:\\nSource transcription requires author review before publication\\n\\nCRITÈRES CLÉS — CORRIGÉ D05\\nMOT DE PASSE\\n\\nRepères de correspondance automatique (suggestion initiale ; validation humaine obligatoire) :\\nMOT DE PASSE\\n\\nLe score automatique utilise les paliers 0\\/25\\/50\\/75\\/100 % selon la couverture des repères configurés. Ce comptage ne remplace pas la grille source ni la correction humaine.\",\"keywords\":\"MOT DE PASSE\",\"answer\":\"\",\"max_points\":1},\"suggestion\":{\"points\":0,\"method\":\"criteria_bands_v3\",\"matched\":[],\"total\":1}}', '2026-10-05 14:02:00'),
