(165, 18, 142, '', 0.00, NULL, NULL, '2026-10-05 12:02:00', 0.00, '{\"version\":1,\"context\":{\"question\":\"10.1 Identifier les techniques et outils de recherche d\'emploi, de formation ou de stage\",\"paragraph\":\"<p>Quels sont les outils que vous utilisez régulièrement dans votre recherche de stage ou emploi ? Présentez 4 exemples concrets d’outils que vous avez déjà mobilisés dans vos anciennes recherches.<\\/p><p>Expliquez comment vous utilisez ces outils et comment vous procédez pour décrocher un emploi\\/stage.<\\/p>\",\"context\":\"\",\"model_answer\":\"10.1 Identifier les techniques et outils de recherche d\'emploi, de formation ou de stage\\nQuels sont les outils que vous utilisez régulièrement dans votre recherche de stage ou emploi ? Présentez 4 exemples concrets d’outils que vous avez déjà mobilisés dans vos anciennes recherches.\\nOutils de l’emploi store : IMT pour comprendre le marché de l’emploi, les enquêtes BMO, les sites et applications de recherche d’emploi : offre d’emploi, LinkedIn, Indeed, etc.\\nExpliquez comment vous utilisez ces outils et comment vous procédez pour décrocher un emploi\\/stage\\nIMT pour comprendre le marché de l’emploi \\/ Linkedin pour consulter des offres d’emploi et l’actualité du secteur \\/ BMo pour cibler les secteurs et métiers qui recrutent ….\",\"rubric\":\"A optimiser : 0-3\\/4☐\\nMaitrisé 4\\/4 ☐\\n\\nSOURCE MARKED ANSWERS (not configured automatic criteria):\\nOutils de l’emploi store : IMT pour comprendre le marché de l’emploi, les enquêtes BMO, les sites et applications de recherche d’emploi : offre d’emploi, LinkedIn, Indeed, etc.\\nIMT pour comprendre le marché de l’emploi \\/ Linkedin pour consulter des offres d’emploi et l’actualité du secteur \\/ BMo pour cibler les secteurs et métiers qui recrutent ….\\n\\nREVIEW:\\nSource transcription requires author review before publication\\n\\nCRITÈRES CLÉS — CORRIGÉ D05\\nOutils de l’emploi store : IMT pour comprendre le marché de l’emploi, les enquêtes BMO, les sites et applications de recherche d’emploi : offre d’emploi, LinkedIn, Indeed, etc.\\nIMT pour comprendre le marché de l’emploi \\/ Linkedin pour consulter des offres d’emploi et l’actualité du secteur \\/ BMo pour cibler les secteurs et métiers qui recrutent ….\\n\\nRepères de correspondance automatique (suggestion initiale ; validation humaine obligatoire) :\\nemploi store\\nIMT\\nBMO\\nLinkedIn|Indeed\\n\\nLe score automatique utilise les paliers 0\\/25\\/50\\/75\\/100 % selon la couverture des repères configurés. Ce comptage ne remplace pas la grille source ni la correction humaine.\",\"keywords\":\"emploi store\\nIMT\\nBMO\\nLinkedIn|Indeed\",\"answer\":\"\",\"max_points\":4},\"suggestion\":{\"points\":0,\"method\":\"criteria_bands_v3\",\"matched\":[],\"total\":4}}', '2026-10-05 14:02:00'),
(166, 18, 143, '', 0.00, NULL, NULL, '2026-10-05 12:02:00', 0.00, '{\"version\":1,\"context\":{\"question\":\"10.2 Identifier les processus de recrutement\",\"paragraph\":\"<p>Voici quelques modes de recrutement utilisés par les entreprises, classez-les par ordre croissant (de 1 à 7) dans le tableau ci-dessous en fonction de leur pourcentage ou fréquence d’utilisation par les entreprises :<\\/p><p>Cabinet de recrutement \\/ Cooptation \\/ Candidatures spontanées \\/ Sites internet d’offre d’emploi \\/ Réseaux sociaux professionnels \\/ Presse \\/ Site internet de l’entreprise<\\/p><table><tbody><tr><td><p>1<\\/p><\\/td><td><p>…………………………..<\\/p><\\/td><\\/tr><tr><td><p>2<\\/p><\\/td><td><p>…………………………..<\\/p><\\/td><\\/tr><tr><td><p>3<\\/p><\\/td><td><p>…………………………..<\\/p><\\/td><\\/tr><tr><td><p>4<\\/p><\\/td><td><p>…………………………..<\\/p><\\/td><\\/tr><tr><td><p>5<\\/p><\\/td><td><p>…………………………..<\\/p><\\/td><\\/tr><tr><td><p>6<\\/p><\\/td><td><p>…………………………..<\\/p><\\/td><\\/tr><tr><td><p>7<\\/p><\\/td><td><p>…………………………..<\\/p><\\/td><\\/tr><\\/tbody><\\/table>\",\"context\":\"\",\"model_answer\":\"10.2 Identifier les processus de recrutement\\nVoici quelques modes de recrutement utilisés par les entreprises, classez-les par ordre croissant (de 1 à 7) dans le tableau ci-dessous en fonction de leur pourcentage ou fréquence d’utilisation par les entreprises :\\nCabinet de recrutement \\/ Cooptation \\/ Candidatures spontanées \\/ Sites internet d’offre d’emploi \\/ Réseaux sociaux professionnels \\/ Presse \\/ Site internet de l’entreprise\\n1Sites internet d’offre d’emploi2Candidatures spontanées3Réseaux sociaux professionnels4Cooptation5Site internet de l’entreprise6Cabinet de recrutement7Presse\",\"rubric\":\"A optimiser : 0-6\\/7☐\\nMaitrisé 7\\/7 ☐\\n\\nSOURCE MARKED ANSWERS (not configured automatic criteria):\\nSites internet d’offre d’emploiCandidatures spontanéesRéseaux sociaux professionnelsCooptationSite internet de l’entrepriseCabinet de recrutementPresse\\n\\nREVIEW:\\nSource transcription requires author review before publication\\n\\nCRITÈRES CLÉS — CORRIGÉ D05\\nSites internet d’offre d’emploiCandidatures spontanéesRéseaux sociaux professionnelsCooptationSite internet de l’entrepriseCabinet de recrutementPresse\\n\\nRepères de correspondance automatique (suggestion initiale ; validation humaine obligatoire) :\\nSites internet d’offre d’emploi\\nCandidatures spontanées\\nRéseaux sociaux professionnels\\nCooptation\\nSite internet de l’entreprise\\nCabinet de recrutement\\nPresse\\n\\nLe score automatique utilise les paliers 0\\/25\\/50\\/75\\/100 % selon la couverture des repères configurés. Ce comptage ne remplace pas la grille source ni la correction humaine.\",\"keywords\":\"Sites internet d’offre d’emploi\\nCandidatures spontanées\\nRéseaux sociaux professionnels\\nCooptation\\nSite internet de l’entreprise\\nCabinet de recrutement\\nPresse\",\"answer\":\"\",\"max_points\":7},\"suggestion\":{\"points\":0,\"method\":\"criteria_bands_v3\",\"matched\":[],\"total\":7}}', '2026-10-05 14:02:00'),
