(168, 18, 145, '', 0.00, NULL, NULL, '2026-10-05 12:02:00', NULL, '{\"version\":1,\"context\":{\"question\":\"10.4. Identifier les entreprises qui recrutent\",\"paragraph\":\"<p>Répondez par vrai ou faux aux propositions suivantes :<\\/p><p>Le marché du travail est le même quel que soit le territoire ?<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>L’enquête BMO porte sur les recrutements réalisés par les entreprises ?<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>L’IMT de Pôle Emploi permet de connaitre le marché de l’emploi<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>Le marché caché du travail correspond aux offres d’emploi en ligne ?<\\/p><p>☐  Vrai      ☐  faux<\\/p>\",\"context\":\"\",\"model_answer\":\"10.4. Identifier les entreprises qui recrutent\\nRépondez par vrai ou faux aux propositions suivantes :\\nLe marché du travail est le même quel que soit le territoire ?\\n☐  Vrai      ☐  faux\\nL’enquête BMO porte sur les recrutements réalisés par les entreprises ?\\n☐  Vrai      ☐  faux\\nL’IMT de Pôle Emploi permet de connaitre le marché de l’emploi\\n☐  Vrai      ☐  faux\\nLe marché caché du travail correspond aux offres d’emploi en ligne ?\\n☐  Vrai      ☐  faux\",\"rubric\":\"A optimiser : 0-3\\/4☐\\nMaitrisé 4\\/4 ☐\\n\\nSOURCE MARKED ANSWERS (not configured automatic criteria):\\nfaux\\nVrai\\n\\nREVIEW:\\nSource transcription requires author review before publication\",\"keywords\":\"\",\"answer\":\"\",\"max_points\":4},\"suggestion\":{\"points\":null,\"method\":\"unconfigured\",\"matched\":[],\"total\":0}}', '2026-10-05 14:02:00'),
(169, 18, 146, '', 0.00, NULL, NULL, '2026-10-05 12:02:00', NULL, '{\"version\":1,\"context\":{\"question\":\"10.5 Mobiliser son réseau personnel et professionnel dans le cadre de sa recherche d’emploi\",\"paragraph\":\"<p>Répondez par vrai ou faux.<\\/p><p>Pour développer mon réseau professionnel, je dois :<\\/p><p>Diffuser mes contacts sur tous les réseaux sociaux<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>Envoyer des mails à un directeur que vous ne connaissez pas du tout<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>Réaliser des enquêtes métiers<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>Demander des recommandations à mes anciens employeurs<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>Inviter des contacts sans aucune stratégie définie<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>Participer à des évènements professionnels<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>M’inscrire sur LinkedIn juste pour réaliser des recherches<\\/p><p>☐  Vrai      ☐  faux<\\/p><p>Envoyer mes candidatures<\\/p><p>☐  Vrai      ☐  faux<\\/p>\",\"context\":\"\",\"model_answer\":\"10.5 Mobiliser son réseau personnel et professionnel dans le cadre de sa recherche d’emploi\\nRépondez par vrai ou faux.\\nPour développer mon réseau professionnel, je dois :\\nDiffuser mes contacts sur tous les réseaux sociaux\\n☐  Vrai      ☒  faux\\nEnvoyer des mails à un directeur que vous ne connaissez pas du tout\\n☐  Vrai      ☒  faux\\nRéaliser des enquêtes métiers\\n☒  Vrai      ☐  faux\\nDemander des recommandations à mes anciens employeurs\\n☒  Vrai      ☐  faux\\nInviter des contacts sans aucune stratégie définie\\n☐  Vrai      ☒  faux\\nParticiper à des évènements professionnels\\n☐  Vrai      ☒  faux\\nM’inscrire sur LinkedIn juste pour réaliser des recherches\\n☐  Vrai      ☒  faux\\nEnvoyer mes candidatures\\n☐  Vrai      ☒  faux\",\"rubric\":\"A optimiser : 0-6\\/7☐\\nMaitrisé 7\\/7 ☐\\n\\nSOURCE MARKED ANSWERS (not configured automatic criteria):\\nfaux\\nVrai\\n\\nREVIEW:\\nSource transcription requires author review before publication\",\"keywords\":\"\",\"answer\":\"\",\"max_points\":7},\"suggestion\":{\"points\":null,\"method\":\"unconfigured\",\"matched\":[],\"total\":0}}', '2026-10-05 14:02:00'),
(170, 18, 147, '', 0.00, NULL, NULL, '2026-10-05 12:02:00', NULL, '{\"version\":1,\"context\":{\"question\":\"10.6 Convaincre en entretien d\'embauche\",\"paragraph\":\"<p>Répondez à l’une des questions suivantes selon votre choix en donnant trois arguments au minimum<\\/p><p>Pourquoi devrions-nous vous embaucher ?<\\/p><p>Comment comptez-vous compenser votre manque d’expérience ?<\\/p>\",\"context\":\"\",\"model_answer\":\"10.6 Convaincre en entretien d\'embauche\\nRépondez à l’une des questions suivantes selon votre choix en donnant trois arguments au minimum\\nPourquoi devrions-nous vous embaucher ?\\nExprimer ses besoins professionnels\\nPrésenter ses motivations\\nMettre en avant ses points forts (diplômes, compétences, expériences)\\nLister des contacts de référents que le recruteur peut contacter\\nDémontrer sa capacité de se projeter dans les missions du poste …\\nComment comptez-vous compenser votre manque d’expérience ?\\nMettre en avant ses compétences, notamment ses Soft Skills et ses réussites.\\nExemple, parler de ses projets scolaires, associatifs, culturel, etc.\",\"rubric\":\"A optimiser : 0-2\\/3☐\\nMaitrisé 3\\/3 ☐\\n\\nSOURCE MARKED ANSWERS (not configured automatic criteria):\\nExprimer ses besoins professionnels\\nPrésenter ses motivations\\nMettre en avant ses points forts (diplômes, compétences, expériences)\\nLister des contacts de référents que le recruteur peut contacter\\nDémontrer sa capacité de se projeter dans les missions du poste …\\nMettre en avant ses compétences, notamment ses Soft Skills et ses réussites.\\nExemple, parler de ses projets scolaires, associatifs, culturel, etc.\\n\\nREVIEW:\\nSource transcription requires author review before publication\\n\\nCRITÈRES CLÉS — CORRIGÉ D05\\nExprimer ses besoins professionnels\\nPrésenter ses motivations\\nMettre en avant ses points forts (diplômes, compétences, expériences)\\nLister des contacts de référents que le recruteur peut contacter\\nDémontrer sa capacité de se projeter dans les missions du poste …\\nMettre en avant ses compétences, notamment ses Soft Skills et ses réussites.\\nExemple, parler de ses projets scolaires, associatifs, culturel, etc.\\n\\nÉvaluation humaine : la réponse dépend de critères qualitatifs, d’un visuel, d’un tableau, d’un choix de question ou d’une situation personnelle. Aucun résultat automatique n’est inventé.\\n\\nLe score automatique utilise les paliers 0\\/25\\/50\\/75\\/100 % selon la couverture des repères configurés. Ce comptage ne remplace pas la grille source ni la correction humaine.\",\"keywords\":\"\",\"answer\":\"\",\"max_points\":3},\"suggestion\":{\"points\":null,\"method\":\"unconfigured\",\"matched\":[],\"total\":0}}', '2026-10-05 14:02:00');
