(105, '[{\"id\":\"f1\",\"type\":\"single_choice\",\"label\":\"Que proclame le 1er article de la déclaration des droits de l’Homme et du Citoyen, adoptée le 26 août 1789 ?\",\"choices\":[\"L’abolition de la peine de mort\",\"Tous les hommes naissent libres et égaux en droit\",\"La liberté de parole\"]},{\"id\":\"f2\",\"type\":\"single_choice\",\"label\":\"Qu’est-ce que Liberté, Egalité, Fraternité ?\",\"choices\":[\"Le titre de l’hymne national\",\"Les couleurs symboliques du drapeau français\",\"La devise de la république française\"]},{\"id\":\"f3\",\"type\":\"multiple_choice\",\"label\":\"Comment puis-je obtenir la nationalité française ?\",\"choices\":[\"Le droit du sang : Avoir un parent au moins français\",\"Le droit du sol : Être né en France\",\"La naturalisation : Faire une demande auprès des services de la préfecture\",\"Le mariage : Être marié(e) à un français pendant 4 ans\"]}]', '{\"type_revision\":2,\"previous_review\":[\"Source transcription requires author review before publication\"],\"choice_corrections\":{\"f1\":{\"correct\":[\"Tous les hommes naissent libres et égaux en droit\"],\"type\":\"single_choice\",\"label\":\"Que proclame le 1er article de la déclaration des droits de l’Homme et du Citoyen, adoptée le 26 août 1789 ?\"},\"f2\":{\"correct\":[\"La devise de la république française\"],\"type\":\"single_choice\",\"label\":\"Qu’est-ce que Liberté, Egalité, Fraternité ?\"},\"f3\":{\"correct\":[\"Le droit du sang : Avoir un parent au moins français\",\"Le droit du sol : Être né en France\",\"La naturalisation : Faire une demande auprès des services de la préfecture\",\"Le mariage : Être marié(e) à un français pendant 4 ans\"],\"type\":\"multiple_choice\",\"label\":\"Comment puis-je obtenir la nationalité française ?\"}},\"source_green\":\"☐Tous les hommes naissent libres et égaux en droit\\n☐La devise de la république française\\n☐Le droit du sang : Avoir un parent au moins français\\n☐Le droit du sol : Être né en France\\n☐La naturalisation : Fai